-- 日常口语对话模块：Learn & Talk I / Chapter 1 Shopping / Lessons 1-7
-- 创建独立表并导入 PDF 中的知识点、示范对话、补全对话、讨论题和拓展词汇。

CREATE TABLE IF NOT EXISTS `daily_spoken_dialogue_item` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `lesson_code` VARCHAR(100) NOT NULL,
    `chapter_title` VARCHAR(200) NOT NULL,
    `lesson_title` VARCHAR(200) NOT NULL,
    `lesson_order` INT NOT NULL DEFAULT 0,
    `section_code` VARCHAR(50) NOT NULL,
    `section_title` VARCHAR(200) NOT NULL,
    `section_order` INT NOT NULL DEFAULT 0,
    `item_type` VARCHAR(50) NOT NULL,
    `item_order` INT NOT NULL,
    `speaker` VARCHAR(100) DEFAULT NULL,
    `item_title` VARCHAR(255) DEFAULT NULL,
    `english_text` LONGTEXT NOT NULL,
    `chinese_text` LONGTEXT DEFAULT NULL,
    `pronunciation` VARCHAR(255) DEFAULT NULL,
    `explanation` LONGTEXT DEFAULT NULL,
    `examples` LONGTEXT DEFAULT NULL,
    `keywords` VARCHAR(500) DEFAULT NULL,
    `is_published` TINYINT(1) NOT NULL DEFAULT 1,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_daily_dialogue_lesson_item` (`lesson_code`, `item_order`),
    KEY `idx_daily_dialogue_lesson_section` (`lesson_code`, `is_published`, `section_order`, `item_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='日常口语对话学习内容表';

    `lesson_code`, `chapter_title`, `lesson_title`, `lesson_order`,
    `section_code`, `section_title`, `section_order`, `item_type`, `item_order`,
    `speaker`, `item_title`, `english_text`, `chinese_text`, `pronunciation`,
    `explanation`, `examples`, `keywords`, `is_published`
) VALUES
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'vocabulary', '核心词汇', 1, 'vocabulary', 1, NULL, 'on sale', 'on sale', '减价的；降价出售的', '/ɑːn seɪl/', 'reduced in price', 'These clothes are on sale now!', 'on sale, sale, shopping', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'vocabulary', '核心词汇', 1, 'vocabulary', 2, NULL, 'try on', 'try on', '试穿；试戴', '/traɪ ɑːn/', 'Put on clothing to see whether it fits or looks nice.', 'May I try on these shoes?', 'try on, fitting room, shopping', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'vocabulary', '核心词汇', 1, 'vocabulary', 3, NULL, 'out of stock', 'out of stock', '缺货的；售罄的', '/aʊt əv stɑːk/', 'A store has sold all of a particular product.', 'I''m sorry. It''s out of stock now.', 'out of stock, sold out, shopping', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'vocabulary', '核心词汇', 1, 'vocabulary', 4, NULL, 'take in', 'take in', '将衣物改小；收紧', '/teɪk ɪn/', 'Make a dress, jacket, or other item of clothing smaller and tighter. Antonym: let out.', 'The dress is loose. I''ll take it in.', 'take in, let out, alter clothes', 1),

    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 101, 'Emma', NULL, 'These clothes are on sale now.', '这些衣服正在打折。', NULL, NULL, NULL, 'on sale, clothes', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 102, 'Mark', NULL, 'Maybe I''ll buy a new shirt.', '也许我要买一件新衬衫。', NULL, NULL, NULL, 'buy a shirt, shopping', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 103, 'Emma', NULL, 'What size are you?', '你穿什么尺码？', NULL, NULL, NULL, 'size, clothes', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 104, 'Mark', NULL, 'XL, but I should try it on. Where''s the fitting room?', 'XL，不过我应该试穿一下。试衣间在哪里？', NULL, NULL, NULL, 'XL, try on, fitting room', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 105, 'Emma', NULL, 'It looks a little loose for you. But size L is out of stock right now.', '它穿在你身上看起来有点松。不过 L 码现在缺货。', NULL, NULL, NULL, 'loose, out of stock, size', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'dialogue', '示范对话', 2, 'dialogue', 106, 'Mark', NULL, 'Then I''ll take it in.', '那我就把它改小。', NULL, NULL, NULL, 'take in, alteration', 1),

    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 201, 'A', NULL, 'Excuse me, can I try on the jeans, please?', '打扰一下，我可以试穿这条牛仔裤吗？', NULL, '使用 try on 发起试穿请求。', NULL, 'try on, jeans', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 202, 'B', NULL, 'Sure. What size are you?', '当然可以。你穿什么尺码？', NULL, NULL, NULL, 'what size, shopping', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 203, 'A', NULL, 'L, I think. Where''s the fitting room?', '我想是 L 码。试衣间在哪里？', NULL, NULL, NULL, 'L, fitting room', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 204, 'B', NULL, 'This way, please.', '请这边走。', NULL, NULL, NULL, 'this way, please', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 205, 'A', NULL, 'It''s a little loose. I think I need an M.', '它有点松。我想我需要 M 码。', NULL, NULL, NULL, 'loose, M size', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 206, 'B', NULL, 'I''m sorry. M is out of stock. These jeans are on sale and they sell so fast. But we can take them in for you.', '抱歉，M 码缺货。这些牛仔裤正在促销，卖得很快。不过我们可以帮你把它们改小。', NULL, '复习 out of stock、on sale 和 take in。', NULL, 'out of stock, on sale, take them in', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'practice', '情景补全对话', 3, 'practice', 207, 'A', NULL, 'That''s great. Thanks.', '太好了，谢谢。', NULL, NULL, NULL, 'thanks, shopping', 1),

    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'discussion', '开口讨论', 4, 'discussion', 301, NULL, 'Where do you usually buy clothes?', 'Where do you usually buy clothes?', '你通常在哪里买衣服？在实体店还是网上？为什么？', NULL, 'In a store → try on clothes\nOn the Internet → shop anytime and anywhere, and clothes may be on sale more often.', NULL, 'buy clothes, in a store, on the Internet', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'discussion', '开口讨论', 4, 'discussion', 302, NULL, 'How often do you buy new clothes? What size do you wear? What clothes do you usually wear?', 'How often do you buy new clothes? What size do you wear? What clothes do you usually wear?', '你多久买一次新衣服？你穿什么尺码？你通常穿什么衣服？', NULL, 'How often → when clothes are on sale / once a season / once a year\nSize → S, M, L, XL\nClothes → shirt / jeans / dress', NULL, 'how often, size, shirt, jeans, dress', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'discussion', '开口讨论', 4, 'discussion', 303, NULL, 'Can you name three clothing brands? What brands do you like?', 'Can you name three clothing brands? What brands do you like?', '你能说出三个服装品牌吗？你喜欢哪些品牌？说说理由。', NULL, 'Reasons → price / style', NULL, 'clothing brands, price, style', 1),

    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'review', '复习表达', 5, 'review', 401, NULL, 'Key expressions', 'What''s your size?\nWhere''s the fitting room?', '常用的买衣服表达：你穿什么尺码？试衣间在哪里？', NULL, '复习本课 4 个词组：on sale / try on / out of stock / take in。', NULL, 'review, size, fitting room', 1),

    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 501, NULL, 'sporty style', 'sporty style', '运动风', NULL, 'A style suitable for sport or inspired by sportswear.', NULL, 'sporty style, fashion', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 502, NULL, 'retro style', 'retro style', '复古风', NULL, 'A style that uses looks from an earlier period.', NULL, 'retro style, fashion', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 503, NULL, 'casual style', 'casual style', '休闲风', NULL, 'Relaxed, informal clothing style.', NULL, 'casual style, fashion', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 504, NULL, 'mountain parka', 'mountain parka', '冲锋衣', NULL, 'A warm jacket with a hood, often used outdoors.', NULL, 'mountain parka, jacket', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 505, NULL, 'Hawaiian shirt', 'Hawaiian shirt', '夏威夷衬衫', NULL, 'A colourful short-sleeved shirt with a tropical print.', NULL, 'Hawaiian shirt, shirt', 1),
    ('buying-clothes', 'Chapter 1 · Shopping', 'Lesson 1 · Buying Clothes', 1, 'extra', '拓展服饰词汇', 6, 'extra', 506, NULL, 'culottes', 'culottes', '女裙裤', NULL, 'Wide-legged trousers that look like a skirt.', NULL, 'culottes, trousers, fashion', 1)
