INSERT INTO `daily_spoken_dialogue_item` (`lesson_code`,`chapter_title`,`lesson_title`,`lesson_order`,`section_code`,`section_title`,`section_order`,`item_type`,`item_order`,`speaker`,`item_title`,`english_text`,`chinese_text`,`pronunciation`,`explanation`,`examples`,`keywords`,`is_published`) VALUES
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'vocabulary','核心词汇',1,'vocabulary',1,NULL,'toothbrush','toothbrush','牙刷','/ˈtuːθbrʌʃ/','a small brush with a long handle that you use to clean your teeth','How much is the toothbrush?','toothbrush, toothpaste, mouthwash',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'vocabulary','核心词汇',1,'vocabulary',2,NULL,'promote','promote','宣传；促销','/prəˈmoʊt/','to encourage people to like, buy, use, do, or support something','The saleswoman is promoting cookies.','promote, promotion',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'vocabulary','核心词汇',1,'vocabulary',3,NULL,'include','include','包括','/ɪnˈkluːd/','to contain something as a part of something else','This gift pack includes toothbrushes, toothpaste, and mouthwash.','include, gift pack',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'vocabulary','核心词汇',1,'vocabulary',4,NULL,'aisle','aisle','（商店货架间的）通道','/aɪl/','a long, narrow space between rows of shelves in a large shop','You''ll find toothbrushes in the fourth aisle.','aisle, supermarket',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'dialogue','示范对话',2,'dialogue',101,'Saleswoman',NULL,'Have a look at these toothbrushes. They are being promoted in this gift pack now.','看看这些牙刷。它们现在正以礼包的形式促销。',NULL,NULL,NULL,'promote, gift pack',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'dialogue','示范对话',2,'dialogue',102,'Emma',NULL,'What''s included in the gift pack?','礼包里包括什么？',NULL,NULL,NULL,'what is included',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'dialogue','示范对话',2,'dialogue',103,'Saleswoman',NULL,'Toothbrushes, toothpaste, mouthwash and a cup!','牙刷、牙膏、漱口水和一个杯子！',NULL,NULL,NULL,'toothbrush, toothpaste',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'dialogue','示范对话',2,'dialogue',104,'Emma',NULL,'It''s a good deal. Where can I find shower gel?','这很划算。在哪里能找到沐浴露？',NULL,NULL,NULL,'good deal, shower gel',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'dialogue','示范对话',2,'dialogue',105,'Saleswoman',NULL,'It''s in aisle 10.','在第 10 条通道。',NULL,NULL,NULL,'aisle',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',201,'A',NULL,'Excuse me. Where can I find toothbrushes?','打扰一下，在哪里能找到牙刷？',NULL,NULL,NULL,'toothbrushes, aisle',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',202,'B',NULL,'In aisle 4. Follow me.','在第 4 条通道。请跟我来。',NULL,NULL,NULL,'aisle',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',203,'A',NULL,'Thanks.','谢谢。',NULL,NULL,NULL,'thanks',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',204,'B',NULL,'Have a look at this pack. It''s being promoted and it is selling well.','看看这个礼包。它正在促销，而且卖得很好。',NULL,NULL,NULL,'promoted, pack',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',205,'A',NULL,'What''s included in the pack?','礼包里包括什么？',NULL,NULL,NULL,'included, pack',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',206,'B',NULL,'Toothbrushes, toothpaste and mouthwash. They''re only 25 yuan in total.','牙刷、牙膏和漱口水，总共只要 25 元。',NULL,NULL,NULL,'toothbrushes, toothpaste, mouthwash',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'practice','情景补全对话',3,'practice',207,'A',NULL,'It''s a good deal.','这很划算。',NULL,NULL,NULL,'good deal',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'discussion','开口讨论',4,'discussion',301,NULL,'When are things in the supermarket promoted in your city? Will you buy a lot when they are being promoted? Why?','When are things in the supermarket promoted in your city? Will you buy a lot when they are being promoted? Why?','你所在城市的超市通常何时促销？促销时你会大量购买吗？为什么？',NULL,'Think about holidays such as Christmas or Women''s Day; low price, good deal, or waste. ',NULL,'promotion, supermarket',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'discussion','开口讨论',4,'discussion',302,NULL,'How often do you go to the supermarket? What do you usually buy there?','How often do you go to the supermarket? What do you usually buy there?','你多久去一次超市？通常买什么？',NULL,'every day / every week / when needed / once in a while; bread / fruit / drinks / shower gel.',NULL,'supermarket, frequency',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'discussion','开口讨论',4,'discussion',303,NULL,'Have you ever bought things in an online supermarket? Do you like it? Why or why not?','Have you ever bought things in an online supermarket? Do you like it? Why or why not?','你在网上超市买过东西吗？喜欢吗？为什么？',NULL,'It is convenient and avoids carrying heavy bags, but delivery can take days.',NULL,'online supermarket, delivery',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'review','复习表达',5,'review',401,NULL,'Key expressions','What''s included in the gift pack? It''s a good deal.','复习：toothbrush / promote / include / aisle。',NULL,NULL,NULL,'review, supermarket',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'extra','拓展购物词汇',6,'extra',501,NULL,'save up to 40%','save up to 40%','最高节省 40%；打六折',NULL,NULL,NULL,'sale, discount',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'extra','拓展购物词汇',6,'extra',502,NULL,'shopping list','shopping list','购物清单',NULL,NULL,NULL,'shopping list',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'extra','拓展购物词汇',6,'extra',503,NULL,'coupon','coupon','优惠券',NULL,NULL,NULL,'coupon, discount',1),
('in-the-supermarket','Chapter 1 · Shopping','Lesson 3 · In the Supermarket',3,'extra','拓展购物词汇',6,'extra',504,NULL,'for sale','for sale','出售中',NULL,'There are lots of items on sale today. That chair is for sale.',NULL,'on sale, for sale',1)
INSERT INTO `daily_spoken_dialogue_item` (`lesson_code`,`chapter_title`,`lesson_title`,`lesson_order`,`section_code`,`section_title`,`section_order`,`item_type`,`item_order`,`speaker`,`item_title`,`english_text`,`chinese_text`,`pronunciation`,`explanation`,`examples`,`keywords`,`is_published`) VALUES
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'vocabulary','核心词汇',1,'vocabulary',1,NULL,'best-seller','best-seller','热卖品；畅销品','/ˌbestˈselər/','a product that has sold a great number of copies','As a writer, he wants to write a best-seller.','best-seller, popular',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'vocabulary','核心词汇',1,'vocabulary',2,NULL,'warranty','warranty','保修单；保修服务','/ˈwɔːrənti/','a written promise to repair or replace a faulty product within a period','The TV has a 3-year warranty.','warranty, repair',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'vocabulary','核心词汇',1,'vocabulary',3,NULL,'offer','offer','提供','/ˈɔːfər/','to provide or supply something','He offered me a glass of water.','offer, provide',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'vocabulary','核心词汇',1,'vocabulary',4,NULL,'delivery','delivery','运送；递送','/dɪˈlɪvəri/','the act of taking goods to people''s homes or workplaces','They offer free delivery, so it''s a good deal.','delivery, deliver',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',101,'Anne',NULL,'How about this one?','这个怎么样？',NULL,NULL,NULL,'how about',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',102,'John',NULL,'I like this brand, and the price isn''t too high.','我喜欢这个品牌，价格也不算太高。',NULL,NULL,NULL,'brand, price',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',103,'John',NULL,'How long is the warranty for this TV?','这台电视的保修期是多久？',NULL,NULL,NULL,'warranty',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',104,'Salesperson',NULL,'It comes with a 2-year parts warranty. It''s also the best-seller now.','它有两年零件保修期，现在也是热卖款。',NULL,NULL,NULL,'parts warranty, best-seller',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',105,'Anne',NULL,'Do you offer free delivery?','你们提供免费送货吗？',NULL,NULL,NULL,'free delivery',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'dialogue','示范对话',2,'dialogue',106,'Salesperson',NULL,'Yes, we do.','是的。',NULL,NULL,NULL,'yes',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'practice','情景补全对话',3,'practice',201,'A',NULL,'Excuse me. How long is the warranty for this air conditioner?','打扰一下，这台空调的保修期是多久？',NULL,NULL,NULL,'warranty, air conditioner',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'practice','情景补全对话',3,'practice',202,'B',NULL,'Three years. It''s the best-seller now. We also offer free delivery.','三年。它现在是热卖款，我们还提供免费送货。',NULL,NULL,NULL,'best-seller, free delivery',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'practice','情景补全对话',3,'practice',203,'A',NULL,'But there''s an air conditioner of this brand in my living room, and it doesn''t work very well recently.','但我家客厅有一台这个品牌的空调，最近不太好用。',NULL,NULL,NULL,'brand, work well',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'practice','情景补全对话',3,'practice',204,'B',NULL,'We''ll offer free repair if it''s still under warranty.','如果还在保修期内，我们会提供免费维修。',NULL,NULL,NULL,'free repair, warranty',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'practice','情景补全对话',3,'practice',205,'A',NULL,'Fine.','好的。',NULL,NULL,NULL,'fine',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'discussion','开口讨论',4,'discussion',301,NULL,'How often do you watch TV? When do you usually watch TV?','How often do you watch TV? When do you usually watch TV?','你多久看一次电视？通常什么时候看？',NULL,'every day / usually / from time to time / never; evening, noon or weekends.',NULL,'watch TV',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'discussion','开口讨论',4,'discussion',302,NULL,'What kind of TV programs do you like? Why?','What kind of TV programs do you like? Why?','你喜欢什么类型的电视节目？为什么？',NULL,'news, talk shows, and variety shows; they can inform, entertain, or relax you.',NULL,'TV programs',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'discussion','开口讨论',4,'discussion',303,NULL,'What will you consider when buying an appliance?','What will you consider when buying an appliance?','买电器时你会考虑哪些因素？',NULL,'Consider brands, prices, warranty length, and whether delivery is free.',NULL,'appliance, warranty',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'review','复习表达',5,'review',401,NULL,'Key expressions','How long is the warranty for this TV? Do you offer free delivery?','复习：warranty / best-seller / offer / delivery。',NULL,NULL,NULL,'review, TV',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'extra','拓展电器词汇',6,'extra',501,NULL,'range hood','range hood','抽油烟机',NULL,NULL,NULL,'appliance, kitchen',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'extra','拓展电器词汇',6,'extra',502,NULL,'electric oven','electric oven','电烤箱',NULL,NULL,NULL,'appliance, kitchen',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'extra','拓展电器词汇',6,'extra',503,NULL,'dishwasher','dishwasher','洗碗机',NULL,NULL,NULL,'appliance, kitchen',1),
('shopping-for-a-tv','Chapter 1 · Shopping','Lesson 4 · Shopping for a TV',4,'extra','拓展电器词汇',6,'extra',504,NULL,'juicer','juicer','果汁机',NULL,NULL,NULL,'appliance, kitchen',1)
INSERT INTO `daily_spoken_dialogue_item` (`lesson_code`,`chapter_title`,`lesson_title`,`lesson_order`,`section_code`,`section_title`,`section_order`,`item_type`,`item_order`,`speaker`,`item_title`,`english_text`,`chinese_text`,`pronunciation`,`explanation`,`examples`,`keywords`,`is_published`) VALUES
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'vocabulary','核心词汇',1,'vocabulary',1,NULL,'top-of-the-line','top-of-the-line','最具水准的；顶级的','/ˌtɑːp əv ðə ˈlaɪn/','of the best quality or among the most expensive available','A top-of-the-line smartphone can replace a computer.','top-of-the-line, smartphone',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'vocabulary','核心词汇',1,'vocabulary',2,NULL,'have access to','have access to','可以使用；可以访问',NULL,'to have the right or opportunity to use something','You''ll have access to the building with the card.','have access to, Internet',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'vocabulary','核心词汇',1,'vocabulary',3,NULL,'out of credit','out of credit','（手机）没话费；（账户）无存款','/aʊt əv ˈkredɪt/','there is no money in your account','I can''t make a phone call. My phone is out of credit.','out of credit, phone',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'vocabulary','核心词汇',1,'vocabulary',4,NULL,'top up','top up','给……加满；充值','/tɑːp ʌp/','to make something full again after part has been used','Let me top up your glass.','top up, recharge',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'dialogue','示范对话',2,'dialogue',101,'John',NULL,'What''s special about this phone?','这部手机有什么特别之处？',NULL,NULL,NULL,'what is special',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'dialogue','示范对话',2,'dialogue',102,'Salesman',NULL,'That''s our top-of-the-line model, and if you choose this carrier, you''ll have unlimited access to the Internet.','那是我们的顶级型号；如果选择这家运营商，就能无限上网。',NULL,NULL,NULL,'top-of-the-line, carrier',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'dialogue','示范对话',2,'dialogue',103,'John',NULL,'I go online a lot with my phone. It easily gets out of credit and I have to top it up twice a month.','我经常用手机上网。它很容易没话费，我每月得充值两次。',NULL,NULL,NULL,'out of credit, top up',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'dialogue','示范对话',2,'dialogue',104,'Salesman',NULL,'Then this really works for you.','那这个确实适合你。',NULL,NULL,NULL,'works for you',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'practice','情景补全对话',3,'practice',201,'A',NULL,'What''s special about this phone?','这部手机有什么特别之处？',NULL,NULL,NULL,'special, phone',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'practice','情景补全对话',3,'practice',202,'B',NULL,'That''s our top-of-the-line model, and you''ll have unlimited access to the Internet.','那是我们的顶级型号，而且可以无限上网。',NULL,NULL,NULL,'top-of-the-line, access',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'practice','情景补全对话',3,'practice',203,'A',NULL,'Well, I don''t need a top-of-the-line one. I don''t need to have access to the Internet, either. All I need is to make phone calls. I make many phone calls at work and my phone easily gets out of credit.','我不需要顶级款，也不需要上网。我只需要打电话；我工作时电话很多，手机很容易没话费。',NULL,NULL,NULL,'access, out of credit',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'practice','情景补全对话',3,'practice',204,'B',NULL,'Then have a look at this one. The carrier provides a discount every time you top up for one year.','那看看这部。运营商为连续一年充值的用户提供折扣。',NULL,NULL,NULL,'carrier, top up, discount',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'practice','情景补全对话',3,'practice',205,'A',NULL,'It works for me.','这很适合我。',NULL,NULL,NULL,'works for me',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'discussion','开口讨论',4,'discussion',301,NULL,'Do you usually make phone calls when you need to contact someone? Why or why not?','Do you usually make phone calls when you need to contact someone? Why or why not?','需要联系别人时你通常打电话吗？为什么？',NULL,'Phone calls are fast and efficient; messaging apps can be cheaper and help avoid shyness.',NULL,'phone call, contact',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'discussion','开口讨论',4,'discussion',302,NULL,'What do you usually do with your smartphone? Which apps do you use most often? Why?','What do you usually do with your smartphone? Which apps do you use most often? Why?','你通常用手机做什么？最常用哪些应用？为什么？',NULL,'Play games, listen to music, take pictures, shop, browse information, or chat with friends.',NULL,'smartphone, apps',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'discussion','开口讨论',4,'discussion',303,NULL,'Do you think it is a waste of time spending too much time on smartphones? What can we do to spend less time on them?','Do you think it is a waste of time spending too much time on smartphones? What can we do to spend less time on them?','你认为在手机上花太多时间是浪费吗？怎样少花一些时间？',NULL,'Delete unnecessary apps, spend more time on real-life hobbies, and take part in social activities.',NULL,'screen time, smartphone',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'review','复习表达',5,'review',401,NULL,'Key expressions','What''s special about this phone? This really works for you.','复习：top-of-the-line / have access to / out of credit / top up。',NULL,NULL,NULL,'review, smartphone',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'extra','拓展手机配件',6,'extra',501,NULL,'selfie stick','selfie stick','自拍杆',NULL,NULL,NULL,'phone accessory',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'extra','拓展手机配件',6,'extra',502,NULL,'phone case','phone case','手机壳',NULL,NULL,NULL,'phone accessory',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'extra','拓展手机配件',6,'extra',503,NULL,'earphone','earphone','耳机',NULL,NULL,NULL,'phone accessory',1),
('buying-a-smartphone','Chapter 1 · Shopping','Lesson 5 · Buying a Smartphone',5,'extra','拓展手机配件',6,'extra',504,NULL,'charger','charger','充电器',NULL,NULL,NULL,'phone accessory',1),
