INSERT INTO `daily_spoken_dialogue_item` (`lesson_code`,`chapter_title`,`lesson_title`,`lesson_order`,`section_code`,`section_title`,`section_order`,`item_type`,`item_order`,`speaker`,`item_title`,`english_text`,`chinese_text`,`pronunciation`,`explanation`,`examples`,`keywords`,`is_published`) VALUES
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'vocabulary','核心词汇',1,'vocabulary',1,NULL,'bargain','bargain','便宜货；协议；交易','/ˈbɑːrɡən/','something on sale below its true value; also an agreement between people','This coat on sale is a real bargain.','bargain, deal',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'vocabulary','核心词汇',1,'vocabulary',2,NULL,'windfall','windfall','意外之财','/ˈwɪndfɔːl/','an amount of money received unexpectedly','Each investor received a windfall of £3,000.','windfall, money',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'vocabulary','核心词汇',1,'vocabulary',3,NULL,'set somebody back','set somebody back','使某人花费（金钱）',NULL,'to cost somebody a particular amount of money','My daughter''s wedding set me back $20,000.','set back, cost',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'vocabulary','核心词汇',1,'vocabulary',4,NULL,'make an exception','make an exception','破例；作为例外',NULL,'not to treat someone according to the usual rules','Would you kindly make an exception for us this time?','exception, bargain',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',101,'Emma',NULL,'How much are these three books?','这三本书多少钱？',NULL,NULL,NULL,'how much',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',102,'Bookseller',NULL,'80 yuan.','80 元。',NULL,NULL,NULL,'price',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',103,'Emma',NULL,'But they set me back only 60 yuan on the Internet. Could you go down on the price?','但网上它们只要 60 元。可以降价吗？',NULL,NULL,NULL,'set back, go down on price',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',104,'Bookseller',NULL,'Maybe I could make an exception for you if you buy four books. 80 yuan for four books. That would be my final offer.','如果你买四本，我也许可以为你破例。四本 80 元，这是我的最终报价。',NULL,NULL,NULL,'make an exception, final offer',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',105,'Emma',NULL,'Alright. That''s a bargain.','好吧。这很划算。',NULL,NULL,NULL,'bargain',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'dialogue','示范对话',2,'dialogue',106,'Bookseller',NULL,'You''ve got a windfall!','你真是得了一笔意外之财！',NULL,NULL,NULL,'windfall',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',201,'A',NULL,'How much is the coat?','这件外套多少钱？',NULL,NULL,NULL,'how much, coat',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',202,'B',NULL,'230 yuan.','230 元。',NULL,NULL,NULL,'price',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',203,'A',NULL,'Could you go down on the price if I buy two coats, please? I''ll also take this shirt.','如果我买两件外套，可以降价吗？我也要这件衬衫。',NULL,NULL,NULL,'go down on the price',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',204,'B',NULL,'Well, I could make an exception for you: 460 yuan for all of these.','嗯，我可以为你破例：这些一共 460 元。',NULL,NULL,NULL,'make an exception',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',205,'A',NULL,'Can I get them for 400?','400 元卖给我可以吗？',NULL,NULL,NULL,'price',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',206,'B',NULL,'Sorry, I can''t do that. 460 at least — that would be my final offer. Actually you''ve got a windfall because this shirt would set you back 80 yuan if you buy it alone.','抱歉，做不到。至少 460 元，这是最终报价。单买这件衬衫要花 80 元，所以你已经占了便宜。',NULL,NULL,NULL,'final offer, windfall, set back',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'practice','情景补全对话',3,'practice',207,'A',NULL,'Well ... Alright, it''s a bargain anyway.','嗯……好吧，反正也算划算。',NULL,NULL,NULL,'bargain',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'discussion','开口讨论',4,'discussion',301,NULL,'What do you think of bargaining? Will you bargain when buying something?','What do you think of bargaining? Will you bargain when buying something?','你怎么看待讨价还价？买东西时会还价吗？',NULL,'It can protect buyers when a price is unreasonable, but some people see it as seeking petty advantages.',NULL,'bargaining, opinion',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'discussion','开口讨论',4,'discussion',302,NULL,'How can buyers bargain successfully? If you were a seller, how would you deal with bargaining?','How can buyers bargain successfully? If you were a seller, how would you deal with bargaining?','买家如何成功还价？如果你是卖家，会怎么应对？',NULL,'Buyers can gather information and ask for small gifts; sellers can set limits or make exceptions for regular buyers.',NULL,'buyer, seller',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'discussion','开口讨论',4,'discussion',303,NULL,'What is the most expensive thing you have ever bought? Did you bargain for it? How did you feel when you finally owned it? Why?','What is the most expensive thing you have ever bought? Did you bargain for it? How did you feel when you finally owned it? Why?','你买过最贵的东西是什么？有还价吗？最后拥有它时感觉如何？',NULL,'Use happy, content, useful, worthwhile, regretful, or unworthy to explain your answer.',NULL,'expensive, bargain',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'review','复习表达',5,'review',401,NULL,'Key expressions','Could you go down on the price? That would be my final offer.','复习：bargain / windfall / set somebody back / make an exception。',NULL,NULL,NULL,'review, bargaining',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'extra','拓展还价表达',6,'extra',501,NULL,'Your prices are pretty steep.','Your prices are pretty steep.','你给出的价格高得不合理。',NULL,NULL,NULL,'price, bargaining',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'extra','拓展还价表达',6,'extra',502,NULL,'I like everything about it except the price.','I like everything about it except the price.','除了价格，我都喜欢。',NULL,NULL,NULL,'price, bargaining',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'extra','拓展还价表达',6,'extra',503,NULL,'Don''t try to rip me off!','Don''t try to rip me off!','别想敲我的竹杠！',NULL,NULL,NULL,'rip off, bargaining',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'extra','拓展还价表达',6,'extra',504,NULL,'Is there any discount on bulk purchases?','Is there any discount on bulk purchases?','批量购买有折扣吗？',NULL,NULL,NULL,'bulk purchase, discount',1),
('bargaining','Chapter 1 · Shopping','Lesson 6 · Bargaining',6,'extra','拓展还价表达',6,'extra',505,NULL,'Deal!','Deal!','成交！',NULL,NULL,NULL,'deal, bargaining',1)
