('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',1,NULL,'check out','check out','结账离开','/tʃek aʊt/','to add up purchases, pay, and leave a supermarket or shop','My father is checking out at the counter.','check out, checkout',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',2,NULL,'error','error','错误','/ˈerər/','a mistake','There are some spelling errors in the letter.','error, mistake',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',3,NULL,'credit card','credit card','信用卡','/ˈkredɪt kɑːrd/','a plastic card used to buy things and pay later','Can I pay by credit card?','credit card, cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',4,NULL,'password','password','口令；密码','/ˈpæswɜːrd/','a secret word or number combination used for identification','You won''t have access to the computer without the password.','password, passcode',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',5,NULL,'change','change','找头；找给的零钱','/tʃeɪndʒ/','money returned after you pay more than the price','You''ve given me the wrong change.','change, cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'vocabulary','核心词汇',1,'vocabulary',6,NULL,'receipt','receipt','发票；收据','/rɪˈsiːt/','a paper that proves money or goods have been received','Make sure you are given a receipt for everything you buy.','receipt, proof',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'dialogue','示范对话',2,'dialogue',101,'Bookseller',NULL,'Would you like to pay by card or in cash?','您想刷卡还是现金支付？',NULL,NULL,NULL,'pay by card, cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'dialogue','示范对话',2,'dialogue',102,'Emma',NULL,'I want to pay by credit card. Do you take Visa?','我想用信用卡支付。你们收 Visa 卡吗？',NULL,NULL,NULL,'credit card, Visa',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'dialogue','示范对话',2,'dialogue',103,'Bookseller',NULL,'Yes we do. Just a moment. Oh, there''s an error. It says your password is incorrect. Could you please try it again?','可以。请稍等。哦，出错了，显示你的密码不正确。请再试一次好吗？',NULL,NULL,NULL,'error, password',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'dialogue','示范对话',2,'dialogue',104,'Emma',NULL,'Well, I completely forgot the password. How about paying in cash?','嗯，我完全忘记密码了。用现金付款怎么样？',NULL,NULL,NULL,'pay in cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'dialogue','示范对话',2,'dialogue',105,'Bookseller',NULL,'Not a problem. Here is your change and your receipt. Have a nice day!','没问题。这是您的找零和收据。祝您愉快！',NULL,NULL,NULL,'change, receipt',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',201,'A',NULL,'Where is the checkout, please?','请问收银台在哪里？',NULL,NULL,NULL,'checkout',1),
('checking-out',gi t'Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',202,'B',NULL,'Over there. Would you like to pay by card or in cash?','在那边。您想刷卡还是现金支付？',NULL,NULL,NULL,'pay by card, cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',203,'A',NULL,'I''ll pay in cash.','我付现金。',NULL,NULL,NULL,'pay in cash',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',204,'B',NULL,'It''s 249 yuan in total.','一共 249 元。',NULL,NULL,NULL,'total',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',205,'A',NULL,'Um ... I don''t have enough cash. May I pay by credit card?','嗯……我的现金不够。可以用信用卡吗？',NULL,NULL,NULL,'cash, credit card',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',206,'B',NULL,'Sure, enter your password here. Sorry, there''s an error. It says your password is incorrect. Try again, please.','可以，请在这里输入密码。抱歉，出现错误，显示你的密码不正确。请再试一次。',NULL,NULL,NULL,'password, error',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',207,'A',NULL,'No problem.','没问题。',NULL,NULL,NULL,'no problem',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'practice','情景补全对话',3,'practice',208,'B',NULL,'Your transaction is completed. Please sign your name here, and here is your receipt.','您的交易已完成。请在这里签名，这是您的收据。',NULL,NULL,NULL,'transaction, receipt',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'discussion','开口讨论',4,'discussion',301,NULL,'What method of payment do you usually use? Why do you usually pay in this way?','What method of payment do you usually use? Why do you usually pay in this way?','你通常用什么支付方式？为什么？',NULL,'Cash can be a habit; cards are useful for expensive items; mobile payment is convenient and avoids carrying cash or cards.',NULL,'payment method',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'discussion','开口讨论',4,'discussion',302,NULL,'Do you have a credit card? When do you usually use it? Why do some people never apply for one?','Do you have a credit card? When do you usually use it? Why do some people never apply for one?','你有信用卡吗？通常什么时候用？为什么有些人从不申请？',NULL,'Use one for expensive items or special benefits. Others control spending, avoid fees, or feel mobile payment is enough.',NULL,'credit card, spending',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'discussion','开口讨论',4,'discussion',303,NULL,'Some people think mobile payment is unsafe. Do you agree or disagree? Why? How can we make it safer?','Some people think mobile payment is unsafe. Do you agree or disagree? Why? How can we make it safer?','有人认为移动支付不安全。你同意吗？为什么？怎样使它更安全？',NULL,'Discuss data leaks, hacking and stolen phones; use face scan, avoid linking every card, and consider insurance.',NULL,'mobile payment, security',1),
('checking-out','Chapter 1 · Shopping','Lesson 7 · Checking Out',7,'review','复习表达',5,'review',401,NULL,'Key expressions','Will you pay by card or in cash? Here is your change and your receipt.','复习：check out / error / credit card / password / change / receipt。',NULL,NULL,NULL,'review, payment',1),
